class ApplyBatchRequest(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    actor: str = Field(
        ...,
        description="Who is applying the plan, under `ClaimRequest.actor`'s rules and for the same reasons: the server trims it, refuses an empty result, anything longer than 256 BYTES (the `maxLength` above counts characters — the byte limit is the binding one), and any control character including newline.\n\nIt is attributed to every item and to the ONE history entry the request records, because a batch is one act by one caller.",
        max_length=256,
        min_length=1,
        pattern='^[^\\u0000-\\u001F\\u007F-\\u009F\\u2028\\u2029]+$',
    )
    force_id_prefix: bool = Field(
        False,
        description="Permits an explicit `create.id` outside the workspace's configured issue prefix, for EVERY create item in the request. Without it such an id is refused by the role and arrives as a `400`.",
    )
    items: list[ApplyItem] = Field(
        ...,
        description='The items to apply, IN THE ORDER THEY ARE TO BE APPLIED. An empty array is a `400` rather than a successful no-op: a write request that writes nothing is a client bug, and answering it cheerfully is how a client whose own plan filtered to nothing silently stops writing.\n\nThe 100-item cap bounds how long one request may hold a write transaction, not batch semantics. Split a larger plan; each request is atomic on its own — but splitting it changes what the end gate can see, since the gate runs over one request at a time.\n\nA per-item refusal names its offender as `items[i].kind.member`.',
        max_length=100,
        min_length=1,
    )
    provenance: str | MISSING = Field(
        MISSING,
        description="Labels the version-control history entry this request records, under `updateIssue`'s rule: it changes how the entry READS, never whether one is recorded. Empty composes a default naming how many items of each kind landed and no ids.",
        max_length=255,
    )
    skip_per_edge_cycle_check: bool = Field(
        False,
        description='Drops the PER-EDGE cycle probe for a caller wiring a large graph, exactly as it does on `POST /v0/beads/dependencies:add`.\n\nIT NEVER DROPS THE END GATE, which runs once after every item and re-validates the whole graph this request built, and it never drops the self-dependency refusal. It trades per-edge attribution for speed, not validation for speed.',
    )


class ApplyBatchInput(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    body: ApplyBatchRequest


